// The event name, when you write it in upcomingConfig.js (EVENT_NAME).
// The letters come in one by one, every letter gives a little sparkle, and then the whole word shines now and then.
// Every design has its own effect (radar, terminal, ticket, launch, neon, glitch, matrix, confetti, git, arcade,
// slot, scratch, chat, comic, news, bsod, clapper, synth, spy, quest),
// and the Upcoming card uses the effect of the popup it belongs to.
//
// You do not edit this file. Just write the name in site/upcomingConfig.js.
import { createElement, useEffect, useMemo, useRef, useState } from 'react';
import { getDesign } from './teaserCore';
import './NameReveal.css';
import './NameRevealNew.css';

export const EFFECTS = ['radar', 'terminal', 'ticket', 'launch', 'neon', 'glitch', 'matrix', 'confetti', 'git', 'arcade', 'slot', 'scratch', 'chat', 'comic', 'news', 'bsod', 'clapper', 'synth', 'spy', 'quest'];

const STEP = { radar: 70, terminal: 90, ticket: 130, launch: 80, neon: 150, glitch: 60, matrix: 65, confetti: 95, git: 70, arcade: 140, slot: 110, scratch: 85, chat: 70, comic: 110, news: 55, bsod: 80, clapper: 100, synth: 70, spy: 90, quest: 100 };   // ms between two letters
const LAND = { radar: 900, terminal: 120, ticket: 600, launch: 900, neon: 700, glitch: 500, matrix: 500, confetti: 900, git: 700, arcade: 700, slot: 800, scratch: 1100, chat: 700, comic: 700, news: 600, bsod: 300, clapper: 700, synth: 1000, spy: 800, quest: 600 };   // ms a letter needs to settle
const SCRAMBLE = new Set(['glitch', 'matrix', 'slot']);   // these swap letters for random signs until each letter locks
const SIGNS = { glitch: 'ABCDEFGHJKLMNPQRSTUVWXYZ0123456789#$%&*<>/', matrix: 'ｱｲｳｴｵｶｷｸｹｺｻｼｽｾｿﾀﾁﾂﾃﾄﾅﾆﾇﾈﾉ0123456789', slot: '7★◆♠♣$BAR7' };
const MAX_TOTAL = 1900;   // a long name never takes more than this to appear (ms)
const START = 320;        // wait after it is on screen (ms)

const reduced = () => !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);

/* split into words and letters (a letter keeps the number it has in the whole name) */
function build(text, restText, all) {
  const out = [];
  let n = 0;
  const add = (str, animate) => str.split(/\s+/).filter(Boolean).forEach((w) => {
    out.push({ w, chars: [...w].map((c) => ({ c, i: animate ? n++ : -1 })), animate, long: w.length > 12 });
  });
  add(text, true);
  if (restText) add(restText, all);
  return { words: out, count: n };
}

/* The heading itself (so the design can still style the h2 / h3).
   text: the event name   rest: the words after it, shown plainly ("is coming")   all: animate the rest as well */
export default function NameReveal({ as = 'h2', text, rest = '', effect = 'radar', all = false, className = '', children, ...props }) {
  const fx = EFFECTS.includes(effect) ? effect : 'radar';
  const full = `${text}${rest ? ` ${rest}` : ''}`;
  const { words, count } = useMemo(() => build(String(text), rest, all), [text, rest, all]);
  const ref = useRef(null);
  const [on, setOn] = useState(false);       // it has been on screen: start
  const [paused, setPaused] = useState(false); // scrolled away: pause the shine
  const [done, setDone] = useState(false);
  const quiet = useMemo(() => reduced(), []);

  const d = Math.max(28, Math.min(STEP[fx], (MAX_TOTAL - LAND[fx]) / Math.max(1, count - 1)));   // gap between letters
  const total = Math.round((count - 1) * d + LAND[fx]);

  useEffect(() => {
    if (quiet) { setOn(true); setDone(true); return undefined; }
    const el = ref.current;
    let t = 0;
    let io = null;
    const start = () => { t = setTimeout(() => setOn(true), START); };
    if (el && 'IntersectionObserver' in window) {
      let first = true;
      io = new IntersectionObserver((es) => {
        const vis = es.some((e) => e.isIntersecting);
        setPaused(!vis);
        if (vis && first) { first = false; start(); }
      }, { threshold: 0.3 });
      io.observe(el);
    } else start();
    return () => { clearTimeout(t); if (io) io.disconnect(); };
  }, [quiet]);

  useEffect(() => {
    if (!on || quiet) return undefined;
    const t = setTimeout(() => setDone(true), total + 250);
    return () => clearTimeout(t);
  }, [on, quiet, total]);

  // glitch + matrix: random signs until each letter locks in
  useEffect(() => {
    if (!on || quiet || !SCRAMBLE.has(fx)) return undefined;
    const el = ref.current;
    if (!el) return undefined;
    const cs = [...el.querySelectorAll('.nr-c[data-i]')];
    const signs = SIGNS[fx];
    const t0 = performance.now();
    const lock = cs.map((c) => Number(c.dataset.i) * d + 340 + Math.random() * 140);
    const tick = () => {
      const t = performance.now() - t0;
      let left = 0;
      cs.forEach((c, k) => {
        if (t >= lock[k]) {
          if (!c.classList.contains('is-lock')) { c.classList.add('is-lock'); c.removeAttribute('data-s'); }
        } else { left += 1; c.setAttribute('data-s', signs[Math.floor(Math.random() * signs.length)]); }
      });
      if (!left) clearInterval(id);
    };
    const id = setInterval(tick, 55);
    tick();
    return () => clearInterval(id);
  }, [on, quiet, fx, d]);

  const cls = `${className} nr-h nr-${fx}${on ? ' is-on' : ''}${done ? ' is-done' : ''}${paused ? ' is-paused' : ''}${quiet ? ' is-quiet' : ''}`.trim();
  const half = Math.ceil(words.length / 2);   // neon: first half pink, second half blue

  return createElement(
    as,
    { ...props, ref, className: cls, 'aria-label': full, style: { '--n': Math.max(1, count), '--d': `${Math.round(d)}ms`, '--T': `${total}ms`, ...(props.style || {}) } },
    <span className="nr-name" aria-hidden="true">
      {words.map((wd, k) => (
        <span key={k}>
          {k > 0 && ' '}
          <span className={`nr-w${wd.long ? ' is-long' : ''}${wd.animate ? '' : ' nr-rest'} ${k < half ? 't1' : 't2'}`}>
            {wd.chars.map((ch, j) => (
              <span
                key={j}
                className="nr-c"
                data-i={ch.i >= 0 ? ch.i : undefined}
                data-k={ch.i >= 0 ? ch.i % 4 : undefined}
                data-last={ch.i === count - 1 ? '1' : undefined}
                style={ch.i >= 0 ? { '--i': ch.i, '--g': `${count > 1 ? Math.round((ch.i / (count - 1)) * 100) : 50}%` } : undefined}
              >{ch.c}</span>
            ))}
          </span>
        </span>
      ))}
    </span>,
    children,
  );
}

/* the title of an Upcoming card: the plain words, or the animated name once EVENT_NAME is written.
   It uses the effect of the popup that goes with the current design. */
export function CardTitle({ t, className, as = 'h3' }) {
  const fx = useMemo(() => getDesign().popup, []);
  return t.name
    ? <NameReveal as={as} className={className} text={t.name} effect={fx} />
    : createElement(as, { className }, t.title);
}
